/*
 * A331382  Numbers whose sum of prime factors is divisible by their product
 *          of prime indices.
 * https://oeis.org/A331382
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = numbers whose sum of prime factors (with multiplicity) is
 *            * divisible by the product of their prime indices (with
 *            multiplicity). * Sequence generated by brute‑force search using
 *            a sieve for smallest * prime factors and prime indices
 * Range:     u8 n <= 23, u16 n <= 55, u32 n <= 55, u64 n <= 55, u128 n <= 55,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/* global state ----------------------------------------------------------*/
static uint32_t *spf = NULL;          /* smallest prime factor of i    */
static uint32_t *prime_index = NULL;  /* 1‑based index of prime i      */
static size_t sieve_limit = 0;        /* current sieve bound           */

static seq_t *seq_cache = NULL;       /* cached sequence values         */
static size_t seq_cache_len = 0;      /* number of cached terms         */
static size_t seq_cache_cap = 0;      /* capacity of cache array        */

static uint64_t last_candidate = 0;   /* last number tested             */
static bool initialized = false;

/* ------------------------------------------------------------------------*/

/* Build a sieve up to 'new_limit', computing spf and prime indices.        */
static void extend_sieve(size_t new_limit)
{
    uint32_t *old_spf = spf;
    uint32_t *old_idx = prime_index;

    spf = (uint32_t*)malloc((new_limit + 1) * sizeof(uint32_t));
    prime_index = (uint32_t*)malloc((new_limit + 1) * sizeof(uint32_t));
    if (!spf || !prime_index) abort();

    /* ---------------------------------------------------------- */
    /* Eratosthenes + smallest prime factor table + index table  */
    /* ---------------------------------------------------------- */
    for (size_t i = 0; i <= new_limit; ++i) {
        spf[i] = 0;
        prime_index[i] = 0;
    }

    uint32_t pcnt = 0;                          /* prime counter (1‑based)      */
    for (uint32_t i = 2; i <= new_limit; ++i) {
        if (spf[i] == 0) {                     /* i is prime                   */
            spf[i] = i;
            pcnt++;
            prime_index[i] = pcnt;
            if ((uint64_t)i * i <= new_limit) {
                for (uint64_t j = (uint64_t)i * i; j <= new_limit; j += i) {
                    if (spf[(size_t)j] == 0)
                        spf[(size_t)j] = i;
                }
            }
        }
    }

    /* Release old arrays if they existed. */
    free(old_spf);
    free(old_idx);

    sieve_limit = new_limit;
}

/* ------------------------------------------------------------------------*/

/* Returns true if n satisfies the condition of the sequence.              */
static bool satisfies(uint64_t n)
{
    if (n == 1) return true;                   /* empty sum = 0 divisible by 1 */

    seq_t sum = 0;
    seq_t prod = 1;

    uint64_t tmp = n;
    while (tmp > 1) {
        uint32_t p = spf[(size_t)tmp];
        uint8_t e = 0;
        while (tmp % p == 0) {
            tmp /= p;
            e++;
        }

        seq_t idx = (seq_t)prime_index[p];

        for (uint8_t k = 0; k < e; ++k) {
            sum += (seq_t)p;                    /* add prime value */

            /* If prod would exceed sum after multiplying idx, fail immediately. */
            if (prod > sum / idx)
                return false;

            prod *= idx;
        }
    }

    return (sum % prod) == 0;
}

/* ------------------------------------------------------------------------*/

/* Main sequence function -------------------------------------------------*/
seq_t a(idx_t n)
{
    if (!initialized) {
        /* Initial sieve size – will grow if necessary. */
        extend_sieve(32768);

        /* Cache initial capacity for the sequence terms. */
        seq_cache_cap = 1024;
        seq_cache = (seq_t*)malloc(seq_cache_cap * sizeof(seq_t));
        if (!seq_cache) abort();

        initialized = true;
    }

    /* Generate terms until we have at least n of them. */
    while (seq_cache_len < (size_t)n) {
        ++last_candidate;
        if ((size_t)last_candidate > sieve_limit) {
            size_t new_limit = sieve_limit * 2;
            if (new_limit < last_candidate * 2)
                new_limit = last_candidate * 2;
            extend_sieve(new_limit);
        }

        if (satisfies(last_candidate)) {
            if (seq_cache_len == seq_cache_cap) {
                seq_cache_cap *= 2;
                seq_cache = (seq_t*)realloc(seq_cache, seq_cache_cap * sizeof(seq_t));
                if (!seq_cache) abort();
            }
            seq_cache[seq_cache_len++] = (seq_t)last_candidate;
        }
    }

    return seq_cache[n - 1];
}
